        category: str | NotGiven = NOT_GIVEN,
        mode: Literal["ACTIVE", "DISABLED", "TEST"] | str | NotGiven = NOT_GIVEN,
        evaluation_mode: Literal["ALL", "ANY"] | str | NotGiven = NOT_GIVEN,
        scope: TransactionRuleScopeParam | NotGiven = NOT_GIVEN,
        conditions: Sequence[TransactionRuleConditionParam] | NotGiven = NOT_GIVEN,
        aggregation: Sequence[TransactionRuleAggregationParam] | NotGiven = NOT_GIVEN,
